 "content": "def transform(grid):
    """Map the less frequent color to 0 and the dominant color to the other color."""
    colors = sorted({value for row in grid for value in row})
    if len(colors) == 1:
        return [[0 for _ in row] for row in grid]
    counts = {value: sum(cell == value for row in grid for cell in row) for value in colors}
    dominant = max(colors, key=lambda value: counts[value])
    other = next(value for value in colors if value != dominant)
    mapping = {dominant: other, other: 0}
    return [[mapping[value] for value in row] for row in grid]

